#requires -Version 7.6
#requires -PSEdition Core
. (Join-Path $PSScriptRoot 'Workspace.ps1')
. (Join-Path $PSScriptRoot 'Process.ps1')
. (Join-Path $PSScriptRoot 'Results.ps1')
. (Join-Path $PSScriptRoot 'Packages.ps1')
. (Join-Path $PSScriptRoot '../UnityHost.ps1')

function Read-YLRegistryAuthoringReceipt {
    param([string] $Path, [object] $HostRecord, [Collections.IDictionary] $Request, [string] $Purpose)
    $receipt = Read-YLPackageEvidenceJson $Path
    if ($receipt['schemaVersion'] -isnot [long] -or $receipt['schemaVersion'] -ne 1 -or $receipt['purpose'] -cne $Purpose -or
        $receipt['hostId'] -cne $HostRecord.id -or $receipt['inputHash'] -cne $Request.inputHash -or
        $receipt['workspaceId'] -cne $Request.workspaceId -or $receipt['resultId'] -cne $Request.resultId -or
        $receipt['entryPackage'] -cne $Request.entryPackage -or $receipt['packageOrigin'] -cne $Request.packageOrigin -or
        $receipt['releaseManifestSha256'] -cne $Request.releaseManifestSha256 -or $receipt['files'] -isnot [array] -or
        $receipt['files'].Count -eq 0 -or $receipt['directories'] -isnot [array] -or $receipt['directories'].Count -eq 0) { throw 'Authoring receipt ownership/source/input identity is invalid.' }
    $prefix = if ($Purpose -ceq 'YLTesting.Samples') { 'Assets/Samples/' } else { $Request.assetDirectory + '/' }
    $seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
    foreach ($file in $receipt['files']) {
        if ($file['path'] -isnot [string] -or -not $file['path'].StartsWith($prefix, [StringComparison]::Ordinal) -or
            $file['sha256'] -isnot [string] -or $file['sha256'] -cnotmatch '^[0-9a-f]{64}$' -or
            $file['guid'] -isnot [string] -or $file['guid'] -cnotmatch '^[0-9a-f]{32}$' -or
            $file['type'] -isnot [string] -or [string]::IsNullOrWhiteSpace($file['type']) -or -not $seen.Add($file['path'])) { throw 'Invalid actual authoring file/meta/type/GUID evidence.' }
        $actual = Get-YLHostManagedPath $HostRecord $file['path']
        if (-not [IO.File]::Exists($actual) -or (Get-FileHash -LiteralPath $actual -Algorithm SHA256).Hash.ToLowerInvariant() -cne $file['sha256']) { throw "Imported/generated bytes changed; preserve them: $($file['path'])" }
    }
    foreach ($directory in $receipt['directories']) {
        if ($directory['path'] -isnot [string] -or $directory['guid'] -isnot [string] -or $directory['guid'] -cnotmatch '^[0-9a-f]{32}$' -or
            $directory['type'] -cne 'UnityEditor.DefaultAsset' -or $directory['metaSha256'] -isnot [string] -or $directory['metaSha256'] -cnotmatch '^[0-9a-f]{64}$') { throw 'Invalid authoring directory/meta evidence.' }
        $allowed = if ($Purpose -ceq 'YLTesting.Samples') { $directory['path'] -ceq 'Assets/Samples' -or $directory['path'].StartsWith('Assets/Samples/', [StringComparison]::Ordinal) } else { $directory['path'] -ceq 'Assets/YLFrameworkData' -or $directory['path'] -ceq $Request.assetDirectory -or $directory['path'].StartsWith($prefix, [StringComparison]::Ordinal) }
        if (-not $allowed) { throw 'Authoring directory receipt escaped its managed output boundary.' }
        $actual = Get-YLHostManagedPath $HostRecord $directory['path']
        if (-not [IO.Directory]::Exists($actual) -or (Get-FileHash -LiteralPath ($actual + '.meta') -Algorithm SHA256).Hash.ToLowerInvariant() -cne $directory['metaSha256']) { throw 'Authoring directory/meta changed.' }
    }
    return $receipt
}

function Read-YLRegistryAuthoringPhase {
    param([Collections.IDictionary] $Request, [object] $ProcessResult, [object] $HostRecord, [Collections.IDictionary] $Release,
        [Collections.IDictionary] $SdkDependencies)
    $reportPath = Join-Path $Request.output 'report.json'
    try { Assert-YLTestProcessSucceeded $ProcessResult } catch {
        if ([IO.File]::Exists($reportPath)) {
            $failed = Read-YLPackageEvidenceJson $reportPath
            throw "Authoring $($Request.phase) process failed ($($ProcessResult.status)): $($failed['error'])"
        }
        throw
    }
    $report = Read-YLPackageEvidenceJson $reportPath
    foreach ($field in @('purpose', 'phase', 'requestId', 'workspaceId', 'hostId', 'cacheId', 'resultId', 'inputHash', 'entryPackage',
        'packageOrigin', 'releaseManifestSha256', 'unityVersion', 'unityProductVersion', 'assetDirectory')) {
        if ($report[$field] -isnot [string] -or $report[$field] -cne $Request[$field]) { throw "Authoring report identity differs: $field" }
    }
    foreach ($field in @('registryUrl', 'registryVersion', 'resolutionRegistryUrl')) {
        if ($null -eq $Request[$field]) {
            if ($null -ne $report[$field]) { throw "Authoring report invented Registry provenance: $field" }
        } elseif ($report[$field] -isnot [string] -or $report[$field] -cne $Request[$field]) { throw "Authoring report source identity differs: $field" }
    }
    if ($report['unityExecutable'] -isnot [string] -or (Get-YLTestPath -Path $report['unityExecutable'] -ReadOnly) -ine $Request.unityExecutable) { throw 'The observed authoring Editor executable differs from the request.' }
    if ($report['schemaVersion'] -isnot [long] -or $report['schemaVersion'] -ne 1 -or $report['status'] -cne 'Completed' -or
        $report['pid'] -isnot [long] -or $report['pid'] -ne $ProcessResult.pid -or $report['isBatchMode'] -isnot [bool] -or -not $report['isBatchMode'] -or
        $report['scriptCompilationFailed'] -isnot [bool] -or $report['scriptCompilationFailed'] -or $report['error'] -cne '' -or
        $report['requestSha256'] -cne (Get-FileHash -LiteralPath (Join-Path $Request.output 'request.json') -Algorithm SHA256).Hash.ToLowerInvariant() -or
        $report['boundaries']['native'] -cne 'NotRun' -or $report['boundaries']['playerHotUpdate'] -cne 'NotVerified') { throw 'Authoring lacks complete ordinary process/compilation/boundary evidence.' }
    Assert-YLRegistryCacheObservation -Actual $report['cacheEnvironment'] -CacheRoot $Request.cacheRoot
    $manifestPath = Get-YLHostManagedPath $HostRecord 'Packages/manifest.json'; $lockPath = Get-YLHostManagedPath $HostRecord 'Packages/packages-lock.json'
    foreach ($item in @(@{ path = $manifestPath; field = 'manifestSha256' }, @{ path = $lockPath; field = 'lockSha256' })) {
        if ($report[$item.field] -cne (Get-FileHash -LiteralPath $item.path -Algorithm SHA256).Hash.ToLowerInvariant()) { throw 'Authoring report does not bind actual manifest/lock bytes.' }
    }
    if ($report['manifestSha256'] -cne $Request.originalManifestSha256) { throw 'The original minimal consumer manifest changed.' }
    $rows = @(foreach ($row in $report['packages']) {
        if ($row -isnot [Collections.IDictionary] -or $row['dependencies'] -isnot [Collections.IDictionary]) { throw 'Authoring has no actual PackageInfo dependency map.' }
        $row
    })
    $graph = Assert-YLRegistryResolvedGraph -Manifest (Read-YLPackageEvidenceJson $manifestPath) -Lock (Read-YLPackageEvidenceJson $lockPath) -Rows $rows -Release $Release -EntryPackage $Request.entryPackage -PackageSource $Request.packageOrigin -RegistryUrl $Request.resolutionRegistryUrl -EditorVersion $Request.unityVersion -HostRoot $Request.hostRoot -CacheRoot $Request.cacheRoot -SdkDependencies $SdkDependencies
    if ($Request.phase -ceq 'Inspect' -and ($report['sample']['status'] -cne 'NotImported' -or $report['sampleAssemblies'].Count -ne 0)) { throw 'Default installation imported/compiled a Sample.' }
    if ($Request.phase -ceq 'Import' -and ($report['sample']['status'] -cne 'Imported' -or $report['sample']['api'] -cne 'UnityEditor.PackageManager.UI.Sample' -or
        $report['sample']['options'] -cne 'None' -or $report['sample']['callIssued'] -isnot [bool] -or -not $report['sample']['callIssued'])) { throw 'No explicit non-overwriting Samples API import was observed.' }
    if ($Request.phase -cin @('Author', 'Reopen') -and ($report['sampleAssemblies'].Count -eq 0 -or $report['authoring']['status'] -cne 'Generated' -or
        $report['authoring']['sentinel'] -isnot [bool] -or $report['authoring']['sentinel'])) { throw 'Sample compilation or actual author-tool generation evidence is missing.' }
    [IO.File]::Copy($manifestPath, (Join-Path $Request.output 'manifest.json'))
    [IO.File]::Copy($lockPath, (Join-Path $Request.output 'packages-lock.json'))
    return @{ phase = $Request.phase; status = 'Completed'; report = $report; graph = $graph; process = $ProcessResult; output = $Request.output }
}

function Invoke-YLRegistryAuthoring {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][object] $Workspace,
        [Parameter(Mandatory)][Collections.IDictionary] $Source,
        [Parameter(Mandatory)][string] $Unity,
        [Parameter(Mandatory)][object] $Editor,
        [Parameter(Mandatory)][ValidateSet('com.kano.ylframework', 'com.kano.ylframework.hybridclr')][string] $EntryPackage,
        [Parameter(Mandatory)][object] $Result,
        [ValidateRange(1, 2147483)][int] $TimeoutSeconds = 900
    )
    Set-StrictMode -Version 3.0
    if ($Source['packageOrigin'] -cnotin @('Registry', 'LocalTarball')) { throw 'Authoring accepts Registry or LocalTarball only.' }
    Assert-YLTestWorkspace $Workspace
    $run = Get-YLTestDirectory -Workspace $Workspace -Path $Result.path
    if ($run.kind -cne 'Result' -or $run.id -cne $Result.id) { throw 'Authoring requires the existing run Result owner.' }
    $Unity = Get-YLTestPath -Path $Unity -ReadOnly
    $null = Get-YLTestEditorProfile -Editors @($Editor) -VersionInfo ([Diagnostics.FileVersionInfo]::GetVersionInfo($Unity))
    if ($Editor.version -cnotin @('2022.3.62f3', '6000.3.27f1')) { throw 'Authoring requires an exact supported standard Editor.' }
    $release = Read-YLRegistryRelease -Path $Source.release.path
    if ($release.sha256 -cne $Source.release.sha256 -or $Source.registryUrl -cne 'https://package.openupm.com' -or $Source.registryVersion -cne $release.packages[0].version) { throw 'Authoring frozen source/release identity changed.' }
    if ($Source.packageOrigin -ceq 'Registry' -and $release.producer['kind'] -cne 'GitHubActions') { throw 'Registry authoring requires the CI producer receipt from Get-YLRegistrySource.' }
    $original = New-YLRegistryHostManifest -PackageSource $Source.packageOrigin -Release $release -EntryPackage $EntryPackage -RegistryUrl $Source.registryUrl
    $sourceFields = Get-YLRegistryRequestFields -Source $Source -EntryPackage $EntryPackage
    $token = [Guid]::NewGuid().ToString('N'); $outputRoot = Get-YLTestPath (Join-Path $run.path ('RegistryAuthoring-' + $token))
    if ([IO.Path]::Exists($outputRoot)) { throw 'Preserve existing authoring evidence.' }
    $null = [IO.Directory]::CreateDirectory($outputRoot)
    $outcome = [ordered]@{ status = 'Failed'; entryPackage = $EntryPackage; packageOrigin = $Source.packageOrigin
        scopeSource = $(if ($Source.packageOrigin -ceq 'Registry') { 'Registry' } else { 'ArtifactPreflight' }); output = $outputRoot; host = $null; cache = $null
        phases = @(); processes = @(); inputIdentity = $null; producerInputs = $null; expectedInputs = $null; sampleReceipt = $null; managedOutputs = $null; reopen = $null
        sourceCommit = $release.sourceCommit; releaseManifestSha256 = $release.sha256
        coldCache = $null; coldInstallCount = 0; boundaries = @{ native = 'NotRun'; playerHotUpdate = 'NotVerified' }; assetDirectory = ('Assets/YLFrameworkData/RegistryAuthoring-' + $token); error = '' }
    $hostLease = $null; $cacheLease = $null; $phaseRecord = $null
    try {
        $expected = Initialize-YLRegistryExpectedInputs -Source $Source -Output (Join-Path $outputRoot 'ExpectedArtifacts')
        $outcome.expectedInputs = $expected
        $sdk = $null
        if ($EntryPackage -ceq 'com.kano.ylframework.hybridclr') {
            $sdk = Get-YLHybridClrRegistrySdk -Approval (Join-Path $Workspace.repository 'PackageSources/com.kano.ylframework.hybridclr/Dependencies.json') -Output (Join-Path $outputRoot 'HybridClrRegistrySdk') -RegistryUrl $Source.registryUrl
            $outcome.boundaries['sdk'] = $sdk.evidence
        }
        $hostRecord = New-YLTestDirectory -Workspace $Workspace -Kind Host -Key ('RA-' + $token)
        $cache = New-YLTestDirectory -Workspace $Workspace -Kind Cache -Key ('RA-' + $token)
        $hostLease = Lock-YLTestDirectory -Workspace $Workspace -Path $hostRecord.path; $cacheLease = Lock-YLTestDirectory -Workspace $Workspace -Path $cache.path
        $outcome.host = $hostRecord; $outcome.cache = $cache
        Assert-YLUnityHostIdle $hostRecord
        $identity = Get-YLTestInputIdentity -Repository $Workspace.repository -Paths @('Tools/Testing/RegistryAuthoringEntry.cs', 'Tools/Testing/Common/RegistryAuthoring.ps1',
            'Tools/Testing/Common/Packages.ps1', 'Tools/Testing/Common/Workspace.ps1', 'Tools/Testing/Common/Process.ps1', 'Tools/Testing/Common/Results.ps1', 'Tools/Testing/UnityHost.ps1') -Toolchain @($Unity) -Profile ('RegistryAuthoring-v1-' + $Editor.productVersion + '-' + $EntryPackage + '-' + $Source.packageOrigin + '-' + $release.sha256 + '-' + $token)
        $outcome.inputIdentity = $identity
        $files = [ordered]@{}
        $files['Assets/RegistryAuthoring/Editor/RegistryAuthoringEntry.cs'] = [IO.File]::ReadAllBytes((Join-Path $Workspace.repository 'Tools/Testing/RegistryAuthoringEntry.cs'))
        $asmdef = @{ name = 'RegistryAuthoring.Editor'; references = @(); includePlatforms = @('Editor'); excludePlatforms = @(); allowUnsafeCode = $false
            overrideReferences = $true; precompiledReferences = @('Newtonsoft.Json.dll'); autoReferenced = $false; defineConstraints = @(); versionDefines = @(); noEngineReferences = $false }
        $files['Assets/RegistryAuthoring/Editor/RegistryAuthoring.asmdef'] = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $asmdef -Depth 8))
        foreach ($relative in @($files.Keys)) {
            $importer = if ($relative.EndsWith('.cs')) { "MonoImporter:`n  externalObjects: {}`n  serializedVersion: 2`n  defaultReferences: []`n  executionOrder: 0`n  icon: {instanceID: 0}`n" } else { "AssemblyDefinitionImporter:`n  externalObjects: {}`n" }
            $files[$relative + '.meta'] = [Text.Encoding]::UTF8.GetBytes("fileFormatVersion: 2`nguid: $([Guid]::NewGuid().ToString('N'))`n" + $importer + "  userData: `n  assetBundleName: `n  assetBundleVariant: `n")
        }
        foreach ($folder in @('Assets/RegistryAuthoring', 'Assets/RegistryAuthoring/Editor')) { $files[$folder + '.meta'] = [Text.Encoding]::UTF8.GetBytes("fileFormatVersion: 2`nguid: $([Guid]::NewGuid().ToString('N'))`nfolderAsset: yes`nDefaultImporter:`n  externalObjects: {}`n  userData: `n  assetBundleName: `n  assetBundleVariant: `n") }
        $files['Packages/manifest.json'] = [Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject $original -Depth 10) + "`n")
        $files['ProjectSettings/ProjectVersion.txt'] = [Text.Encoding]::UTF8.GetBytes("m_EditorVersion: $($Editor.version)`n")
        Sync-YLUnityHost -HostRecord $hostRecord -Files $files -Identity $identity -EditorVersion $Editor.version
        $outcome.producerInputs = Read-YLPackageEvidenceJson (Join-Path $hostRecord.path '.yl-inputs.json')
        $before = Join-Path $outputRoot 'manifest.before.json'; [IO.File]::Copy((Join-Path $hostRecord.path 'Packages/manifest.json'), $before)
        $releasePath = Join-Path $outputRoot 'release-manifest.json'; [IO.File]::Copy($release.path, $releasePath)
        $inputReceiptHash = (Get-FileHash -LiteralPath (Join-Path $hostRecord.path '.yl-inputs.json') -Algorithm SHA256).Hash.ToLowerInvariant()
        $originalManifestHash = (Get-FileHash -LiteralPath $before -Algorithm SHA256).Hash.ToLowerInvariant()
        $sampleReceiptHash = ''; $managedReceiptHash = ''
        $initialGraph = $null; $initialPackages = $null; $authorReport = $null; $initialReportHash = ''
        foreach ($phase in @('Inspect', 'Import', 'Author', 'Reopen')) {
            $output = Join-Path $outputRoot $phase; $null = [IO.Directory]::CreateDirectory($output)
            $phaseRecord = @{ phase = $phase; status = 'Failed'; reportPath = (Join-Path $output 'report.json'); process = $null; output = $output; error = '' }
            $outcome.phases += $phaseRecord
            Assert-YLUnityHostIdle $hostRecord
            foreach ($owner in @($hostRecord, $cache, $run)) { if ((Get-YLTestDirectory -Workspace $Workspace -Path $owner.path).id -cne $owner.id) { throw 'Authoring host/cache/result ownership changed.' } }
            foreach ($pinned in @(@{ path = (Join-Path $hostRecord.path '.yl-inputs.json'); sha256 = $inputReceiptHash },
                @{ path = $before; sha256 = $originalManifestHash }, @{ path = $releasePath; sha256 = $release.sha256 },
                @{ path = (Join-Path $hostRecord.path '.yl-samples.json'); sha256 = $sampleReceiptHash },
                @{ path = (Join-Path $hostRecord.path '.yl-authoring-outputs.json'); sha256 = $managedReceiptHash })) {
                if ($pinned.sha256 -and (Get-FileHash -LiteralPath (Get-YLTestPath $pinned.path) -Algorithm SHA256).Hash.ToLowerInvariant() -cne $pinned.sha256) { throw 'Frozen producer/sample/output receipt changed; do not adopt externally rewritten bytes.' }
            }
            $request = @{ schemaVersion = 1; purpose = 'YLTesting.RegistryAuthoring'; requestId = [Guid]::NewGuid().ToString('N'); phase = $phase; packageOrigin = $Source.packageOrigin
                workspaceRoot = $Workspace.root; workspaceId = $Workspace.id; repository = $Workspace.repository; hostRoot = $hostRecord.path; hostId = $hostRecord.id; cacheRoot = $cache.path; cacheId = $cache.id
                resultRoot = $run.path; resultId = $run.id; authoringRoot = $outputRoot; output = $output; inputHash = $identity.sha256
                unityExecutable = $Unity; unityVersion = $Editor.version; unityProductVersion = $Editor.productVersion
                inputReceiptSha256 = $inputReceiptHash
                originalManifest = $before; originalManifestSha256 = $originalManifestHash
                releaseManifest = $releasePath; releaseManifestSha256 = $release.sha256; entryPackage = $EntryPackage
                registryUrl = $sourceFields.registryUrl; registryVersion = $sourceFields.registryVersion; resolutionRegistryUrl = $Source.registryUrl
                initialReportSha256 = $initialReportHash
                assetDirectory = $outcome.assetDirectory; baselineDirectory = (Join-Path $hostRecord.path 'RegistryAuthoringBaseline')
                sampleReceiptSha256 = $sampleReceiptHash; managedReceiptSha256 = $managedReceiptHash }
            $requestPath = Join-Path $output 'request.json'; Write-YLTestJson -Path $requestPath -Value $request
            $start = [Diagnostics.ProcessStartInfo]::new($Unity); $start.UseShellExecute = $false; $start.WorkingDirectory = $hostRecord.path
            foreach ($key in @($start.Environment.Keys | Where-Object { $_.StartsWith('GIT_', [StringComparison]::OrdinalIgnoreCase) })) { $null = $start.Environment.Remove($key) }
            $start.Environment['UPM_CACHE_ROOT'] = Join-Path $cache.path 'Upm'; $start.Environment['UPM_CACHE_PATH'] = Join-Path $cache.path 'Upm/packages'
            $start.Environment['UPM_NPM_CACHE_PATH'] = Join-Path $cache.path 'Upm/npm'; $start.Environment['UPM_GIT_LFS_CACHE_PATH'] = Join-Path $cache.path 'Lfs'
            if ($phase -ceq 'Inspect') { $outcome.coldCache = Assert-YLRegistryColdCache -StartInfo $start -CacheRoot $cache.path }
            foreach ($argument in @('-batchmode', '-nographics', '-projectPath', $hostRecord.path, '-executeMethod', 'YLFramework.Testing.RegistryAuthoringEntry.Execute', '-ylRegistryAuthoringRequest', $requestPath, '-logFile', (Join-Path $output 'unity.log'))) { $start.ArgumentList.Add($argument) }
            $fact = Invoke-YLTestProcess -StartInfo $start -Log (Join-Path $output 'process.log') -TimeoutMilliseconds ([long]$TimeoutSeconds * 1000)
            $phaseRecord.process = $fact
            $outcome.processes += $fact
            $sdkDependencies = if ($null -ne $sdk) { $sdk.dependencies } else { @{} }
            $resultPhase = Read-YLRegistryAuthoringPhase -Request $request -ProcessResult $fact -HostRecord $hostRecord -Release $release -SdkDependencies $sdkDependencies
            foreach ($field in $resultPhase.Keys) { $phaseRecord[$field] = $resultPhase[$field] }
            $graphJson = ConvertTo-Json -InputObject $resultPhase.graph.packages -Depth 20 -Compress
            $packageJson = ConvertTo-Json -InputObject $resultPhase.report.packageFiles -Depth 20 -Compress
            if ($phase -ceq 'Inspect') { $initialGraph = $graphJson; $initialPackages = $packageJson; $outcome.coldInstallCount = 1; $initialReportHash = (Get-FileHash -LiteralPath (Join-Path $output 'report.json') -Algorithm SHA256).Hash.ToLowerInvariant() }
            elseif ($graphJson -cne $initialGraph -or $packageJson -cne $initialPackages) { throw 'Import/authoring/warm reopen changed actual installation identity or cached package bytes.' }
            if ($null -ne $sdk) {
                $installed = @($resultPhase.graph.packages | Where-Object { $_.name -ceq 'com.code-philosophy.hybridclr' })
                if ($installed.Count -ne 1) { throw 'Actual indirect HybridCLR SDK is missing.' }
                Assert-YLHybridClrRegistryInstalled -Sdk $sdk -Root $installed[0].resolvedPath
            }
            if ($phase -cne 'Inspect') {
                $path = Join-Path $hostRecord.path '.yl-samples.json'
                $outcome.sampleReceipt = Read-YLRegistryAuthoringReceipt -Path $path -HostRecord $hostRecord -Request $request -Purpose 'YLTesting.Samples'
                $actualHash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()
                if ($actualHash -cne $resultPhase.report.sampleReceiptSha256 -or ($sampleReceiptHash -and $actualHash -cne $sampleReceiptHash)) { throw 'Actual Sample receipt differs from its first observed process evidence.' }
                if (-not $sampleReceiptHash) { $sampleReceiptHash = $actualHash }
            }
            if ($phase -cin @('Author', 'Reopen')) {
                $path = Join-Path $hostRecord.path '.yl-authoring-outputs.json'
                $outcome.managedOutputs = Read-YLRegistryAuthoringReceipt -Path $path -HostRecord $hostRecord -Request $request -Purpose 'YLTesting.RegistryAuthoring.Outputs'
                $actualHash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()
                if ($actualHash -cne $resultPhase.report.managedReceiptSha256 -or ($managedReceiptHash -and $actualHash -cne $managedReceiptHash)) { throw 'Actual output receipt differs from its first observed process evidence.' }
                if (-not $managedReceiptHash) { $managedReceiptHash = $actualHash }
            }
            if ($phase -ceq 'Author') { $authorReport = $resultPhase.report }
            if ($phase -ceq 'Reopen') {
                if ($resultPhase.report.sampleReceiptSha256 -cne $request.sampleReceiptSha256 -or $resultPhase.report.managedReceiptSha256 -cne $request.managedReceiptSha256 -or
                    (ConvertTo-Json -InputObject $resultPhase.report.authoring -Depth 20 -Compress) -cne (ConvertTo-Json -InputObject $authorReport.authoring -Depth 20 -Compress)) { throw 'Warm reopen did not preserve exact actual authoring outputs/types/GUIDs.' }
                $outcome.reopen = @{ status = 'Unchanged'; meaning = 'SameVersionWarmReopenNotUpgrade'; report = (Join-Path $output 'report.json'); sampleReceiptSha256 = $request.sampleReceiptSha256; managedReceiptSha256 = $request.managedReceiptSha256 }
            }
        }
        $fresh = Get-YLTestInputIdentity -Repository $Workspace.repository -Paths @($identity.files.path) -Toolchain @($Unity) -Profile $identity.profile
        if ($fresh.sha256 -cne $identity.sha256 -or (Get-FileHash -LiteralPath $Source.release.path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $release.sha256) { throw 'Authoring producer/toolchain/release inputs drifted.' }
        $outcome.status = 'Completed'
    } catch {
        $outcome.error = $_.Exception.Message
        if ($null -ne $phaseRecord) { $phaseRecord.status = 'Failed'; $phaseRecord.error = $outcome.error }
        if ($outcome.error.StartsWith('PrerequisiteNotMet:', [StringComparison]::Ordinal)) { $outcome.status = 'PrerequisiteNotMet' }
    } finally {
        if ($null -ne $cacheLease) { $cacheLease.Dispose() }; if ($null -ne $hostLease) { $hostLease.Dispose() }
    }
    return [pscustomobject]$outcome
}
